{
  "name": "EMA cross",
  "spec": {
    "version": 2,
    "market": {
      "venue": "delta_india",
      "instrument": "perpetual",
      "symbols": [
        {
          "symbol": "BTCUSDT"
        }
      ],
      "direction": "long",
      "marginMode": "isolated",
      "leverage": 3
    },
    "session": {
      "interval": "1h",
      "timezone": "UTC",
      "mode": "24_7",
      "windows": []
    },
    "entry": {
      "long": {
        "match": "all",
        "conditions": [
          {
            "left": {
              "kind": "indicator",
              "id": "ema",
              "output": "value",
              "params": {
                "length": 9
              }
            },
            "operator": "crosses_above",
            "right": {
              "kind": "indicator",
              "id": "ema",
              "output": "value",
              "params": {
                "length": 21
              }
            }
          }
        ]
      },
      "short": null,
      "atTimes": null
    },
    "exit": {
      "onOppositeSignal": false,
      "long": null,
      "short": null
    },
    "risk": {
      "takeProfit": {
        "mode": "rr",
        "value": 2
      },
      "stopLoss": {
        "mode": "pct",
        "value": 2
      },
      "trailing": null,
      "timeStopBars": null,
      "partials": [],
      "breakEvenAtR": null
    },
    "sizing": {
      "mode": "risk_pct",
      "value": 1
    },
    "advanced": {
      "entryType": "market",
      "limitOffsetPct": 0.2,
      "limitExpiryBars": 3,
      "reentryCooldownBars": 0,
      "maxTradesPerDay": null
    },
    "limits": {
      "dailyLossPct": null,
      "maxConsecutiveLosses": null
    }
  }
}

